<template><main class="mx-auto max-w-[1600px] px-4 py-6 md:px-7">
<div class="flex flex-col gap-3 lg:flex-row lg:items-end lg:justify-between"><div><NuxtLink to="/admin/products" class="text-sm font-bold text-blue-600">← Products</NuxtLink><p class="mt-4 text-xs font-black uppercase tracking-[.16em] text-blue-600">Bulk Product Import</p><h1 class="text-3xl font-black text-slate-950">Import Leader Category</h1><p class="mt-1 text-slate-500">Import directly from Leader supplier data. No vendor website lookup is performed.</p></div><NuxtLink to="/admin/products/import-supplier-url" class="secondary">Single Product Import</NuxtLink></div>
<div v-if="error" class="mt-5 rounded-xl border border-red-200 bg-red-50 p-4 text-sm font-bold text-red-700">{{error}}</div><div v-if="message" class="mt-5 rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-sm font-bold text-emerald-700">{{message}}</div>
<section class="panel mt-5 p-5"><div class="grid gap-4 lg:grid-cols-[220px_1fr_260px_auto] lg:items-end"><label class="field"><span>Supplier</span><select v-model.number="supplierId" class="input"><option :value="0">Select Leader supplier…</option><option v-for="s in suppliers" :key="s.id" :value="Number(s.id)">{{s.name}}</option></select></label><label class="field"><span>Leader Category URL</span><input v-model.trim="url" class="input" placeholder="https://partner.leadersystems.com.au/categories.html?..." /></label><label class="field"><span>Leader Category</span>
<select v-if="categoryOptions.length" v-model="categoryOverride" class="input">
<option value="">Select category…</option>
<option v-for="c in categoryOptions" :key="c.code" :value="c.name">{{ c.name }} ({{ c.code }})</option>
</select>
<input v-else v-model.trim="categoryOverride" class="input" placeholder="Auto-detect / category name" />
</label><button class="primary" :disabled="fetching||!supplierId||!url" @click="fetchCategory">{{fetching?'Loading…':'Fetch Category'}}</button></div><p class="mt-3 text-xs text-slate-500">The importer resolves Leader's display category to its internal code using ProductCategory (for example Hard Disk Drives - SSD → HB), then sends that code to GetProducts.</p></section>
<template v-if="result"><section class="panel mt-5 p-5"><div class="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between"><div><p class="eyebrow">Leader Category</p><h2 class="text-2xl font-black">{{result.category}}</h2><p class="text-sm text-slate-500">{{result.count}} products · {{result.subcategories.length}} subcategories · Leader code {{result.category_code}}</p></div><div class="flex flex-wrap gap-2"><button class="secondary" @click="selectMode('vic')">Select VIC Stock</button><button class="secondary" @click="selectMode('any')">Select Any Stock</button><button class="secondary" @click="selectMode('new')">Select New</button><button class="secondary" @click="selectMode('all')">Select All</button><button class="secondary" @click="selected=[]">Clear</button><button class="primary" :disabled="importing||!selected.length" @click="importSelected">{{importing?`Importing ${progress}/${selected.length}…`:`Import Selected (${selected.length})`}}</button></div></div>
<div class="mt-4 flex flex-wrap gap-2"><button v-for="sub in result.subcategories" :key="sub" class="rounded-full border px-3 py-1.5 text-xs font-bold" :class="subFilter===sub?'border-blue-600 bg-blue-600 text-white':'border-slate-300 bg-white text-slate-700'" @click="subFilter=subFilter===sub?'':sub">{{sub}}</button></div></section>
<section class="mt-5 overflow-x-auto rounded-2xl border border-slate-200 bg-white shadow-sm"><table class="min-w-[1400px] w-full text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="p-3"><input type="checkbox" :checked="visible.length&&visible.every(p=>selected.includes(p.supplier_sku))" @change="toggleVisible"></th><th class="p-3 text-left">Product</th><th class="p-3 text-left">Leader SKU</th><th class="p-3 text-left">Subcategory</th><th class="p-3 text-right">Buy ex GST</th><th class="p-3 text-right">RRP</th><th class="p-3 text-center">VIC</th><th class="p-3 text-center">NSW</th><th class="p-3 text-center">QLD</th><th class="p-3 text-center">SA</th><th class="p-3 text-center">WA</th><th class="p-3 text-left">Status</th></tr></thead><tbody><tr v-for="p in visible" :key="p.supplier_sku" class="border-t"><td class="p-3 text-center"><input v-model="selected" type="checkbox" :value="p.supplier_sku"></td><td class="p-3"><div class="flex items-center gap-3"><img v-if="p.images?.[0]" :src="p.images[0]" class="h-14 w-14 rounded-lg border object-contain p-1"><div><p class="font-bold text-slate-900">{{p.name}}</p><p class="text-xs text-slate-500">{{p.brand}} · {{p.mpn}}</p></div></div></td><td class="p-3 font-mono text-xs">{{p.supplier_sku}}</td><td class="p-3">{{p.leader_subcategory}}</td><td class="p-3 text-right font-bold">{{money(p.buy_price_ex_gst)}}</td><td class="p-3 text-right">{{money(p.rrp_inc_gst)}}</td><td class="p-3 text-center font-bold">{{p.stock_by_state.VIC}}</td><td class="p-3 text-center">{{p.stock_by_state.NSW}}</td><td class="p-3 text-center">{{p.stock_by_state.QLD}}</td><td class="p-3 text-center">{{p.stock_by_state.SA}}</td><td class="p-3 text-center">{{p.stock_by_state.WA}}</td><td class="p-3"><span v-if="p.status==='existing'" class="badge amber">Existing — will move/category-link</span><span v-else class="badge green">New product</span></td></tr></tbody></table></section></template>
</main></template>
<script setup lang="ts">definePageMeta({layout:'admin',middleware:['admin']});const {adminFetch}=useAdminFetch();const suppliers=ref<any[]>([]),supplierId=ref(0),url=ref(''),categoryOverride=ref(''),result=ref<any>(null),categoryOptions=ref<any[]>([]),selected=ref<string[]>([]),subFilter=ref(''),fetching=ref(false),importing=ref(false),progress=ref(0),error=ref(''),message=ref('');const visible=computed(()=>result.value?.products?.filter((p:any)=>!subFilter.value||p.leader_subcategory===subFilter.value)||[]);const money=(v:any)=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(Number(v||0));async function fetchCategory(){fetching.value=true;error.value='';message.value='';selected.value=[];try{const r:any=await adminFetch('/api/admin/products/import-category/fetch',{method:'POST',body:{url:url.value,category:categoryOverride.value}});categoryOptions.value=r.categories||[];result.value=r.needs_category?null:r;if(r.category)categoryOverride.value=r.category;if(r.needs_category)message.value='Leader categories loaded. Select the matching Leader category and click Fetch Category again.'}catch(e:any){error.value=e?.data?.statusMessage||e?.message||'Unable to fetch Leader category.'}finally{fetching.value=false}}function selectMode(mode:string){const ps=result.value?.products||[];selected.value=ps.filter((p:any)=>mode==='all'||mode==='new'&&p.status==='new'||mode==='vic'&&Number(p.stock_by_state?.VIC)>0||mode==='any'&&Number(p.stock_total)>0).map((p:any)=>p.supplier_sku)}function toggleVisible(e:any){const codes=visible.value.map((p:any)=>p.supplier_sku);selected.value=e.target.checked?[...new Set([...selected.value,...codes])]:selected.value.filter(x=>!codes.includes(x))}async function importSelected(){importing.value=true;progress.value=0;error.value='';message.value='';const chosen=(result.value?.products||[]).filter((p:any)=>selected.value.includes(p.supplier_sku));let created=0,moved=0,failed=0;for(const p of chosen){try{const r:any=await adminFetch('/api/admin/products/import-category/import',{method:'POST',body:{supplier_id:supplierId.value,product:p}});r.action==='created'?created++:moved++}catch(e:any){failed++;error.value=`${p.supplier_sku}: ${e?.data?.statusMessage||e?.message||'Import failed'}`}finally{progress.value++}}message.value=`Import complete: ${created} created, ${moved} existing products moved/linked, ${failed} failed.`;importing.value=false;await fetchCategory()}onMounted(async()=>{try{suppliers.value=await adminFetch('/api/admin/products/suppliers');const leader=suppliers.value.find((s:any)=>/leader/i.test(s.name));if(leader)supplierId.value=Number(leader.id)}catch(e:any){error.value=e?.message||'Unable to load suppliers.'}})</script>
<style scoped>.panel{@apply rounded-2xl border border-slate-200 bg-white shadow-sm}.primary{@apply inline-flex items-center justify-center rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-black text-white hover:bg-blue-700 disabled:opacity-50}.secondary{@apply inline-flex items-center justify-center rounded-lg border border-slate-300 bg-white px-4 py-2.5 text-sm font-bold text-slate-700 hover:bg-slate-50}.field{@apply grid gap-1.5 text-xs font-black uppercase tracking-wide text-slate-500}.input{@apply w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm font-normal normal-case tracking-normal text-slate-900}.eyebrow{@apply text-xs font-black uppercase tracking-[.14em] text-blue-600}.badge{@apply inline-flex rounded-full px-2 py-1 text-[10px] font-black uppercase}.badge.green{@apply bg-emerald-100 text-emerald-700}.badge.amber{@apply bg-amber-100 text-amber-800}</style>